"""String tables for the four site languages. English is the source; the other
three are written for a driver, not translated word for word. Keys are shared
across languages so a template can call S[lang][key]."""

LANGS = ["en", "nl", "de", "fr"]
PREFIX = {"en": "", "nl": "/nl", "de": "/de", "fr": "/fr"}
CITY_NAME = {  # display names where they differ from English
    "nl": {"The Hague": "Den Haag"}, "de": {"The Hague": "Den Haag"}, "fr": {"The Hague": "La Haye"}, "en": {},
}
CITY_SLUG_WORD = {"nl": "parkeren", "de": "parken", "fr": "stationnement"}   # /nl/parkeren-amsterdam

def city_name(lang, en_name): return CITY_NAME.get(lang, {}).get(en_name, en_name)
def city_url(lang, slug): return f"/{slug}" if lang == "en" else f"{PREFIX[lang]}/{CITY_SLUG_WORD[lang]}-{slug}"
def garage_url(lang, slug): return f"{PREFIX[lang]}/garage/{slug}"

def money(lang, v):
    if v is None: return "n/a"
    s = f"{v:,.2f}"
    if lang == "en": return "€" + s
    s = s.replace(",", "X").replace(".", ",").replace("X", ".")
    return ("€" + s) if lang != "fr" else (s + " €")

def num(lang, v):
    if v is None: return "n/a"
    s = f"{v:,}"
    if lang == "en": return s
    return s.replace(",", ".") if lang != "fr" else s.replace(",", " ")

def pct(lang, v, d=0):
    s = f"{v:.{d}f}%"
    return s if lang == "en" else s.replace(".", ",")

